void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    fragColor=texture(iChannel0,fragCoord/(iResolution.xy*resize));
}

const int MAX_STEPS=10000;
const float MIN_DISTANCE=0.0001;
const float MAX_DISTANCE=100.0;

const vec3 mat_color=vec3(0.0,0.5,1.0);
const float mat_density=0.1;

//perlin noise
float smoothlerp (float a, float b, float x) {
   float t = x * x * (3.0f - 2.0f * x);

   return a + t*(b-a);
}
float hash(vec3 seed){
    vec3 M1=vec3(3.1251,17.8737,40.0);
    float M2=43758.545312;
    return fract(sin(dot(seed,M1))*M2)*2.0-1.0;
}

float perlin(vec3 point, float scale){
    vec3 block=floor(point/scale)*scale;
    vec3 dis=fract(point/scale);

    vec3 t=vec3(scale,scale,0.0);
    vec3 v1=normalize(vec3(hash(block),hash(block+vec3(1.0)),hash(block+vec3(2.0))));
    vec3 v2=normalize(vec3(hash(block+t.xzz),hash(block+t.xzz+vec3(1.0)),hash(block+t.xzz+vec3(2.0))));
    vec3 v3=normalize(vec3(hash(block+t.zyz),hash(block+t.zyz+vec3(1.0)),hash(block+t.zyz+vec3(2.0))));
    vec3 v4=normalize(vec3(hash(block+t.xyz),hash(block+t.xyz+vec3(1.0)),hash(block+t.xyz+vec3(2.0))));

    vec3 v5=normalize(vec3(hash(block+t.zzx),hash(block+t.zzx+vec3(1.0)),hash(block+t.zzx+vec3(2.0))));
    vec3 v6=normalize(vec3(hash(block+t.xzx),hash(block+t.xzx+vec3(1.0)),hash(block+t.xzx+vec3(2.0))));
    vec3 v7=normalize(vec3(hash(block+t.zyx),hash(block+t.zyx+vec3(1.0)),hash(block+t.zyx+vec3(2.0))));
    vec3 v8=normalize(vec3(hash(block+t.xxx),hash(block+t.xxx+vec3(1.0)),hash(block+t.xxx+vec3(2.0))));

    float d1=dot(dis,v1);
    float d2=dot(dis-vec3(1.0,0.0,0.0),v2);
    float d3=dot(dis-vec3(0.0,1.0,0.0),v3);
    float d4=dot(dis-vec3(1.0,1.0,0.0),v4);

    float d5=dot(dis-vec3(0.0,0.0,1.0),v5);
    float d6=dot(dis-vec3(1.0,0.0,1.0),v6);
    float d7=dot(dis-vec3(0.0,1.0,1.0),v7);
    float d8=dot(dis-vec3(1.0,1.0,1.0),v8);


    return smoothlerp(smoothlerp(smoothlerp(d1,d2,dis.x),smoothlerp(d3,d4,dis.x),dis.y),smoothlerp(smoothlerp(d5,d6,dis.x),smoothlerp(d7,d8,dis.x),dis.y),dis.z);
}

//distances
//sphere
float dis_sphere(vec3 point, vec3 center, float radious){
    return distance(point,center)-radious;
}
float dis_cube(vec3 ray, vec3 center, vec3 dim){
    vec3 point = abs(center - ray) - dim;
    return length(max(point, 0.0)) + min(max(point.x, max(point.y, point.z)), 0.0);
}

//booleans
//union
float OR(float a, float b){
    return min(a,b);
}
//cut
float NOT(float a, float b){
    return max(a,-b);
}
//intesection
float AND(float a, float b){
    return max(a,b);
}

//scene
float dis_scene(vec3 point){
    float sp1=dis_sphere(point,vec3(0.0,0.0,3.0),2.0);
    float sp2=dis_sphere(point,vec3(2.0,1.0,4.0),2.0);
    float sp3=dis_sphere(point,vec3(2.0,-1.0,3.0),1.0);
    float cu1=dis_cube(point,vec3(-1.0,1.0,0.0),vec3(3.0));
    float cu2=dis_cube(point,vec3(0.0,-12.0,0.0),vec3(10.0));
    return OR(OR(NOT(OR(sp1,sp2),sp3),cu1),cu2);
}

//ray
float ray_density(vec3 ori, vec3 dir){
    bool is_inside=dis_scene(ori)<0.0;
    float prevtot=0.0;
    float segmentdis=0.0;
    float densitytot=0.0;

    float distot=0.0;

    for (int paso=0; paso<MAX_STEPS; paso++){
        vec3 ray = ori + dir*distot;

        float dist=dis_scene(ray);

        distot+=abs(dist);
        segmentdis+=abs(dist);

        if (dist<MIN_DISTANCE){
            if (is_inside){
                /*
                //supose density per point is (cos(ray.z)+1.0)
                //the integral is (sin(ray.z)+ray.z)
                //so we use the defined integral between the last pt and the first of the segment
                float curz=ori.z+dir.z*distot;
                float prevz=ori.z+dir.z*prevtot;
                densitytot+=( (sin(curz)+curz) - (sin(prevz)+prevz) );*/
                //now with noise
                for (float d=prevtot; d<distot; d+=0.005){
                    vec3 vray=ori+dir*d+vec3(iTime);
                    densitytot+=(0.5+perlin(vray+vec3(iTime),1.0)/2.0)*0.005;
                }
            }
            segmentdis=0.0;
            is_inside=dis_scene(ray)<0.0;//!is_inside;
            prevtot=distot;
            distot+=0.00001;
        }
        /*
        is_inside=dis_scene(ray)<0.0;
        distot+=0.1;
        if (is_inside){
                densitytot+=(cos(ray.z)+1.0)/2.0*0.1;
            }*/

        if (distot>MAX_DISTANCE){
            break;
        }
    }

    return densitytot;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    if (fragCoord.x>iResolution.x/resize || fragCoord.y>iResolution.y/resize)
        return;

    float fov=60.0;
    float aspect_ratio=iResolution.y/iResolution.x;
    float sc = tan(fov*0.5*3.14159265359/180.0);

    vec2 p=(fragCoord*resize/iResolution.xy*2.0-1.0)*sc;
    p.x/=aspect_ratio;

    vec3 dir=normalize(vec3(p,1.0));

    vec3 ori=vec3(2.0,1.0,-7.0)+vec3(cos(iTime),0.0,sin(iTime))*5.0;

    float dis=ray_density(ori,dir);

    float opacity=exp(dis*mat_density)-1.0;

    vec3 ogcolor=vec3(1.0);

    vec3 outcolor=ogcolor*(1.0-opacity)+mat_color*opacity;

    fragColor=vec4(outcolor,1.0);
}
